// Logitech's tables are static const arrays of keyboard_led. The
// controller builds a key_set from pointer and count (lines 471 and 1979).

struct named { const void* p; const char* n; };

static const char* lookup(const named* t, size_t count, const void* p)
{
    for(size_t i = 0; i < count; i++) if(t[i].p == p) return t[i].n;
    return "?";
}

static bool same(const keyboard_led& a, const keyboard_led& b)
{
    return a.zone == b.zone && a.row == b.row && a.col == b.col && a.value == b.value && a.opcode == b.opcode
        && strcmp(a.name, b.name) == 0 && strcmp(a.alt_name, b.alt_name) == 0;
}

static bool same(const key_set& a, const key_set& b)
{
    if(a.size() != b.size()) return false;
    for(size_t i = 0; i < a.size(); i++) if(!same(a[i], b[i])) return false;
    return true;
}

static bool same(const keyboard_keymap_overlay_values& a, const keyboard_keymap_overlay_values& b)
{
    if(a.base_size != b.base_size || a.key_values.default_values != b.key_values.default_values) return false;
    if(a.key_values.regional_overlay.size() != b.key_values.regional_overlay.size()) return false;
    for(const auto& o : a.key_values.regional_overlay)
    {
        auto it = b.key_values.regional_overlay.find(o.first);
        if(it == b.key_values.regional_overlay.end() || !same(o.second, it->second)) return false;
    }
    return same(a.edit_keys, b.edit_keys);
}

static const char* layout_names[] = { "Default", "AnsiQwerty", "IsoQwerty", "IsoQwertz", "IsoAzerty", "Jis", "Abnt2" };

static void dump(FILE* f, const char* family, const char* recipe, int layout, KeyboardLayoutManager& k)
{
    fprintf(f, "case\t%s\t%s\t%s\t%u\t%u\t%u\t%s\n", family, recipe, layout_names[layout],
            k.GetRowCount(), k.GetColumnCount(), k.GetKeyCount(), k.GetName().c_str());
    for(unsigned int i = 0; i < k.GetKeyCount(); i++)
    {
        fprintf(f, "%u\t%u\t%u\t%s\t%s\n", k.keymap[i].row, k.keymap[i].col, k.GetKeyValueAt(i),
                k.GetKeyNameAt(i).c_str(), k.GetKeyAltNameAt(i).c_str());
    }
    matrix_map_type m = k.GetKeyMap(KEYBOARD_MAP_FILL_TYPE_COUNT);
    fprintf(f, "map\t%u\t%u", m.height, m.width);
    for(unsigned int c = 0; c < m.map.size(); c++) fprintf(f, "\t%d", (int)m.map[c]);
    fprintf(f, "\n");
}

